const { env } = await import('node:process');
if (!env.CMD) { throw new Error('Missing CMD env var'); }
globalThis.command = env.CMD;
globalThis.args = env.ARGS ? env.ARGS.split(' ') : [];

const { spawn } = await import('node:child_process');
await new Promise((resolve, reject) => {
  const proc = spawn(globalThis.command, globalThis.args);
  let stdout = '';
  let stderr = '';
  proc.stdout.on('data', d => { stdout += d.toString(); });
  proc.stderr.on('data', d => { stderr += d.toString(); });
  proc.on('error', err => reject(err));
  proc.on('close', code => {
    if (code !== 0) { reject(new Error(`Command exited with code ${code}: ${stderr}`)); }
    else { globalThis.result = stdout.trim(); resolve(); }
  });
});
